def swept_mid(e, ang, dzc, th0, z0):
    """centre of the surface swept from edge e=(p,q) over [th0,th0+ang], lifted from z0"""
    m = 0.5*(e[0]+e[1]); th = th0+ang/2
    return np.array([m[0]*math.cos(th), m[0]*math.sin(th), m[1]+z0+dzc/2])

